void ClearFieldDataFromGrid(vtkDataSet* grid)
{
  if (grid)
  {
    grid->GetPointData()->Initialize();
    grid->GetCellData()->Initialize();
    // probably don't need to clear out field data but just being safe
    grid->GetFieldData()->Initialize();
  }
}

