//----------------------------------------------------------------------------
void vtkSession::Activate()
{
  if (vtkProcessModule* pm = vtkProcessModule::GetProcessModule())
  {
    pm->PushActiveSession(this);
  }
}

//----------------------------------------------------------------------------
void vtkSession::DeActivate()
{
  if (vtkProcessModule* pm = vtkProcessModule::GetProcessModule())
  {
    pm->PopActiveSession(this);
  }
}

