{
  this->Dimensions[0] = xdim;
  this->Dimensions[1] = ydim;
  this->Dimensions[2] = zdim;

  this->WholeExtent[1] = this->WholeExtent[0] + xdim - 1;
  this->WholeExtent[3] = this->WholeExtent[2] + ydim - 1;
  this->WholeExtent[5] = this->WholeExtent[4] + zdim - 1;

  this->Modified();
}

