bool vtkEqual(vtkStringArray* self, vtkStringArray* other)
{
  if (self->GetNumberOfValues() != other->GetNumberOfValues())
  {
    return false;
  }
  for (vtkIdType cc = 0, max = self->GetNumberOfValues(); cc < max; cc++)
  {
    if (self->GetValue(cc) != other->GetValue(cc))
    {
      return false;
    }
  }
  return true;
}
